import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"0039 — A Host API lane is minted for one of exactly two reasons","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0039-a-lane-is-minted-for-one-of-two-reasons.md","filePath":"spec/decisions/0039-a-lane-is-minted-for-one-of-two-reasons.md"}'),i={name:"spec/decisions/0039-a-lane-is-minted-for-one-of-two-reasons.md"};function s(r,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_0039-—-a-host-api-lane-is-minted-for-one-of-exactly-two-reasons" tabindex="-1">0039 — A Host API lane is minted for one of exactly two reasons <a class="header-anchor" href="#_0039-—-a-host-api-lane-is-minted-for-one-of-exactly-two-reasons" aria-label="Permalink to &quot;0039 — A Host API lane is minted for one of exactly two reasons&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-22</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0038-a-generation-move-is-measured-not-assumed.html">Decision 0038</a> recorded a question and declined to answer it: two normative documents in this repository appeared to disagree about whether a maturity graduation may mint a new Host API lane.</p><p><a href="./../versioning.html"><code>../versioning.md</code></a> says the lane does not move for Form reasons — <em>&quot;a Host wire version never implies Form maturity&quot;</em>, and <em>&quot;The API group MUST NOT graduate based on a Form count, package publication, provider major, historical admission, or one host&#39;s conformance report.&quot;</em></p><p><a href="./0035-beta-contracts-ship-in-stable-provider-v2-1.html">Decision 0035</a> and <a href="./../publication-freeze.html"><code>../publication-freeze.md</code></a> say a graduation arrives as a new identity — <em>&quot;Stable <code>v1</code> and Form <code>1.0.0</code> are new exact identities&quot;</em>, <em>&quot;Promotion adds identities and create defaults.&quot;</em></p><p>They do not disagree. They answer <strong>different questions</strong>, and reading them as one produced the deadlock:</p><ul><li><code>versioning.md</code> answers <strong>what may cause a lane to move</strong>.</li><li><code>0035</code> answers <strong>what a move looks like when one is warranted</strong>.</li></ul><p>A rule that satisfies both is available, and this record adopts it. What forced the earlier deferral was reading &quot;the lane must not graduate on Form grounds&quot; as &quot;the lane must not graduate&quot;, which is not what it says.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>A lane is minted for the wire contract changing, or for the lane itself advancing a maturity channel on the evidence <code>versioning.md</code> names. Nothing else.</strong> Not because a Form Family moved, not because Forms changed, not because a provider was released.</p><p><strong>A graduation mints a new exact identity; it never relabels an occupied one.</strong><a href="./0037-immutability-begins-at-stable.html">Decision 0037</a> settles this half: a served identity means what it meant when it was published. A lane published at a Beta channel asserted that channel — the site derives and publishes it from that word — so graduating it in place would make an address a reader already holds quietly mean something stronger than it did. That is the failure this repository spent a whole change set removing, and it is not worth re-introducing to save one migration.</p><p>The migration a graduation costs is bounded and final. <code>alpha → beta → stable</code> has no further step, so the move to a stable lane is the last maturity-driven lane move that can ever happen. A permanent false name is the worse trade.</p><p><strong>Both halves are enforced rather than described.</strong> Every lane is recorded with the reason it was minted. A <code>protocol</code> lane&#39;s wire contract must differ structurally from every other <code>protocol</code> lane&#39;s, with version words normalised so a rename cannot present itself as a contract; a graduation lane is exempt from that comparison precisely because carrying an existing contract under a new channel is what it is for. A <code>graduation</code> lane must state which prerequisite it satisfied, because no comparison of bytes can establish it.</p><h2 id="what-this-says-about-the-lane-that-exists" tabindex="-1">What this says about the lane that exists <a class="header-anchor" href="#what-this-says-about-the-lane-that-exists" aria-label="Permalink to &quot;What this says about the lane that exists&quot;">​</a></h2><p><code>forms.takoform.com/v1beta1</code> is recorded as a graduation whose lane-specific evidence was never stated. It was minted with the Edge family channel move, and its wire contract is structurally identical to <code>v1alpha3</code>&#39;s — 590 lines each, indistinguishable once version words are normalised, with the normative document differing by a single line that is a link. Under the rule above it would have had to say what it graduated on, and it did not.</p><p>It is frozen into Registry-published provider <code>v2.1.1</code> and cannot be withdrawn. The record therefore stands as history rather than as a precedent, and the gate reads it as the exception it is. What the rule prevents is the next one.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The deadlock 0038 recorded is resolved without either document being wrong, and without changing any identity that exists.</p><p>A future stable lane is still permitted, still requires the five prerequisites in <code>versioning.md</code>, and now also requires saying which of them it met. A future protocol lane is permitted and must prove it carries a different contract.</p><p>What is no longer permitted is the thing that happened: a lane moving because everything else did, with no reason recorded for the lane in particular. The family and the Forms may move on their own axes without dragging the wire identity with them, which is what <code>versioning.md</code> said all along.</p>',21)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
